// Helper para construir fracciones reales de 2 pisos (numerador arriba, denominador abajo) en Roboto
function Frac(num, den) {
  return `<span class="frac"><span class="num">${num}</span><span class="den">${den}</span></span>`;
}

function Sqrt(rad) {
  return `<span class="sqrt-wrap"><span class="sqrt-sign">√</span><span class="sqrt-radicand">${rad}</span></span>`;
}

// ============================================================================
// 1. ESTRELLAS ANIMADAS QUE PULSAN LENTAMENTE EN EL FONDO DE LA NEBULOSA
// ============================================================================
function initStarfieldAnimation() {
  const canvas = document.getElementById("starfieldCanvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  let w = (canvas.width = window.innerWidth);
  let h = (canvas.height = window.innerHeight);

  const stars = Array.from({ length: 68 }, () => ({
    x: Math.random() * w,
    y: Math.random() * h,
    r: 0.7 + Math.random() * 1.9,
    baseAlpha: 0.2 + Math.random() * 0.55,
    speed: 0.004 + Math.random() * 0.012,
    phase: Math.random() * Math.PI * 2,
    hue: Math.random() > 0.45 ? "251, 191, 36" : "56, 189, 248"
  }));

  window.addEventListener("resize", () => {
    w = canvas.width = window.innerWidth;
    h = canvas.height = window.innerHeight;
  });

  function drawStars() {
    ctx.clearRect(0, 0, w, h);
    for (const s of stars) {
      s.phase += s.speed;
      const alpha = Math.max(0.08, Math.min(0.95, s.baseAlpha + Math.sin(s.phase) * 0.32));
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${s.hue}, ${alpha.toFixed(3)})`;
      ctx.shadowBlur = 8;
      ctx.shadowColor = `rgba(${s.hue}, ${alpha.toFixed(3)})`;
      ctx.fill();
    }
    requestAnimationFrame(drawStars);
  }
  requestAnimationFrame(drawStars);
}

