function toggleFormulaDrawer() {
  isFormulaDrawerOpen = !isFormulaDrawerOpen;
  const drawer = document.getElementById("formulaDrawerLeft");
  const btn = document.getElementById("btnFormulaDrawerToggle");
  const img = document.getElementById("capyFormulaToggleImg");

  if (drawer) drawer.classList.toggle("open", isFormulaDrawerOpen);
  if (btn) btn.classList.toggle("open", isFormulaDrawerOpen);
  if (img) {
    // Cambia del capibara con banana al capibara con bata de laboratorio cuando está abierta
    img.src = isFormulaDrawerOpen ? "assets/capy_labcoat.webp" : "assets/capy_banana.webp";
  }
}

function renderFormulaSheet(unitKey) {
  ["u6", "u7", "u8"].forEach(k => {
    const b = document.getElementById("fTab_" + k);
    if (b) {
      b.className = k === unitKey
        ? "px-3 py-1 rounded-full text-xs font-bold bg-amber-400 text-slate-950 font-tier-3"
        : "px-3 py-1 rounded-full text-xs font-bold bg-slate-800 text-slate-200 hover:bg-slate-700 font-tier-3";
    }
  });

  const container = document.getElementById("formulaDrawerContent");
  if (!container) return;
  const list = FORMULA_SHEET_DATA[unitKey] || FORMULA_SHEET_DATA.u6;

  container.innerHTML = list.map(item => `
    <div class="math-showcase-box !my-0 !p-3.5 space-y-1.5">
      <div class="text-sm font-bold text-amber-300 font-tier-2">${item.name}</div>
      ${item.exprHtml}
      <div class="border-t border-slate-700/60 pt-1.5">${item.despejesHtml}</div>
      <div class="text-xs text-slate-200 pt-1 font-sans leading-relaxed">${item.vars}</div>
    </div>
  `).join("");
}

// ============================================================================
// 3. MENÚ Y VISOR DESPLEGABLE 'ARCHIVOS' (EN FORMATO ORIGINAL Y SIN TAPAR LA BARRA STICKY)
// ============================================================================
function toggleArchivosMenu() {
  const menu = document.getElementById("archivosDropdownMenu");
  if (menu) menu.classList.toggle("hidden");
}

function openOriginalFileViewer(fileKey, pageNumber = 1) {
  const menu = document.getElementById("archivosDropdownMenu");
  if (menu) menu.classList.add("hidden");

  const panel = document.getElementById("archivosViewerPanel");
  const titleEl = document.getElementById("archivosViewerTitle");
  const jumpSel = document.getElementById("archivosPageJumpSelect");
  const scrollBox = document.getElementById("archivosPagesScrollContainer");

  const docData = ORIGINAL_FILES[fileKey] || ORIGINAL_FILES.u6;
  if (!panel || !scrollBox || !docData) return;

  panel.classList.remove("hidden");
  if (titleEl) titleEl.textContent = docData.title;

  if (jumpSel) {
    jumpSel.innerHTML = docData.pages.map((_, idx) =>
      `<option value="${idx + 1}" ${idx + 1 === pageNumber ? 'selected' : ''}>Ir a Página ${idx + 1} de ${docData.pages.length}</option>`
    ).join("");
  }

  scrollBox.innerHTML = docData.pages.map((dataUri, idx) => `
    <div id="origPage_${idx + 1}" class="max-w-3xl mx-auto bg-slate-900/80 p-3 md:p-4 rounded-2xl shadow-2xl space-y-2 text-center">
      <div class="text-xs font-bold text-amber-300 font-tier-3">
        ${docData.title} — Página ${idx + 1} de ${docData.pages.length}
      </div>
      <img src="${dataUri}" alt="Página original ${idx + 1}" class="w-full h-auto rounded-xl mx-auto shadow-lg bg-white">
    </div>
  `).join("");

  setTimeout(() => {
    scrollToOriginalPage(pageNumber);
  }, 60);
}

function scrollToOriginalPage(pageNum) {
  const target = document.getElementById("origPage_" + pageNum);
  if (target) {
    target.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function closeOriginalFileViewer() {
  const panel = document.getElementById("archivosViewerPanel");
  if (panel) panel.classList.add("hidden");
}

