// ============================================================================
// 6. FUNCIONES DE LOS SIMULADORES CON PARÁMETROS DEL DESARROLLO TEÓRICO
// ============================================================================
function updateTheorySim1() {
  const q1El = document.getElementById("sl_c1_q1");
  const q2El = document.getElementById("sl_c1_q2");
  const dEl = document.getElementById("sl_c1_d");
  if (!q1El || !q2El || !dEl) return;

  const q1 = parseFloat(q1El.value);
  const q2 = parseFloat(q2El.value);
  const d = parseFloat(dEl.value);

  document.getElementById("val_c1_q1").textContent = (q1 > 0 ? "+" : "") + q1;
  document.getElementById("val_c1_q2").textContent = (q2 > 0 ? "+" : "") + q2;
  document.getElementById("val_c1_d").textContent = d.toFixed(1);

  const k = 9e9;
  const fN = (k * Math.abs(q1 * 1e-6 * q2 * 1e-6)) / (d * d);
  const isAttract = (q1 * q2) < 0;
  const isZero = (q1 === 0 || q2 === 0);

  const gapPx = Math.round(40 + d * 48);
  const stage = document.getElementById("vis_c1_stage");
  if (stage) {
    stage.innerHTML = `
      <div class="flex items-center justify-center transition-all duration-300" style="gap: ${gapPx}px;">
        <div class="flex flex-col items-center">
          <div class="w-12 h-12 rounded-full flex items-center justify-center font-bold text-slate-950 shadow-lg ${q1 > 0 ? 'bg-amber-400' : q1 < 0 ? 'bg-cyan-400' : 'bg-slate-400'}">
            ${q1 > 0 ? '+' : q1 < 0 ? '−' : '0'}
          </div>
          <span class="text-xs text-slate-300 mt-1">q₁ = ${q1} μC</span>
        </div>

        <div class="text-center font-bold text-sm ${isZero ? 'text-slate-400' : isAttract ? 'text-emerald-300' : 'text-rose-300'}">
          ${isZero ? 'Sin Fuerza (Carga Neutra)' : isAttract ? '⟶ ⟵ ATRACCIÓN' : '⟵ ⟶ REPULSIÓN'}
          <div class="text-xs text-slate-400">d = ${d.toFixed(1)} m</div>
        </div>

        <div class="flex flex-col items-center">
          <div class="w-12 h-12 rounded-full flex items-center justify-center font-bold text-slate-950 shadow-lg ${q2 > 0 ? 'bg-amber-400' : q2 < 0 ? 'bg-cyan-400' : 'bg-slate-400'}">
            ${q2 > 0 ? '+' : q2 < 0 ? '−' : '0'}
          </div>
          <span class="text-xs text-slate-300 mt-1">q₂ = ${q2} μC</span>
        </div>
      </div>
    `;
  }

  const out = document.getElementById("out_c1_result");
  if (out) {
    out.textContent = `F_elec = ${fN.toFixed(4)} N  (${isZero ? 'Cargas sin interacción' : isAttract ? 'Fuerza Atractiva por signos opuestos' : 'Fuerza Repulsiva por signos iguales'})`;
  }
}

function updateTheorySim2() {
  const matEl = document.getElementById("sel_c2_mat");
  const vEl = document.getElementById("sl_c2_v");
  if (!matEl || !vEl) return;

  const mat = matEl.value;
  const v = parseFloat(vEl.value);
  document.getElementById("val_c2_v").textContent = v;

  const info = {
    metal: { r: 2, desc: "Electrones libres de la capa externa desplazándose con mínima oposición.", icon: "⚡⚡⚡ Alta Corriente de Electrones" },
    sangre: { r: 8, desc: "Iones hidratados (Na⁺, Cl⁻, K⁺) desplazándose en ambos sentidos por el plasma.", icon: "🧪⚡ Conducción Electrolítica Bidireccional" },
    semi: { r: 40, desc: "Cristal de Silicio dopado: conduce de forma controlada para amplificar o conmutar.", icon: "🎛️ Corriente Regulada (Transistor)" },
    super: { r: 0, desc: "Resistencia exactamente NULA (R = 0 Ω): corriente persistente sin pérdida calórica.", icon: "🧲✨ Supercorriente sin Efecto Joule (RMN)" },
    aislante: { r: 1000000, desc: "Electrones fuertemente unidos al núcleo: no hay electrones libres ni paso de corriente.", icon: "🛡️ Corriente Bloqueada (I ≈ 0 A)" }
  }[mat];

  const iVal = info.r === 0 ? "Máxima sin disipación (R = 0 Ω)" : (v / info.r).toFixed(4) + " A";
  const stage = document.getElementById("vis_c2_stage");
  if (stage) {
    stage.innerHTML = `
      <div class="text-base font-bold text-amber-300">${info.icon}</div>
      <div class="text-sm text-slate-200">${info.desc}</div>
      <div class="text-sm font-mono text-cyan-300 pt-1">Resistencia estimada: ${info.r} Ω &nbsp;|&nbsp; Intensidad resultante a ${v} V: ${iVal}</div>
    `;
  }
}

function updateTheorySim3() {
  const typeEl = document.getElementById("sel_c3_type");
  const qEl = document.getElementById("sl_c3_q");
  const tEl = document.getElementById("sl_c3_t");
  if (!typeEl || !qEl || !tEl) return;

  const type = typeEl.value;
  const q = parseFloat(qEl.value);
  const t = parseFloat(tEl.value);
  document.getElementById("val_c3_q").textContent = q;
  document.getElementById("val_c3_t").textContent = t;

  const iAmp = q / t;
  const iMa = iAmp * 1000;
  const stage = document.getElementById("vis_c3_stage");
  if (stage) {
    stage.innerHTML = `
      <div class="text-base font-bold text-amber-300">
        ${type === "ca"
          ? "〰️ Onda Sinusoidal de 50 Hz (+220 V a -220 V): Los electrones vibran 50 veces por segundo en el lugar"
          : "➡️ Tensión Constante de Batería: Los electrones avanzan continuamente en un único sentido"}
      </div>
      <div class="text-sm font-mono text-cyan-200">
        Intensidad calculada: I = ${q} C / ${t} s = <strong>${iAmp.toFixed(2)} A</strong> (${iMa.toFixed(0)} mA)
      </div>
    `;
  }
}

function updateTheorySim4() {
  const vEl = document.getElementById("sl_c4_v");
  const rEl = document.getElementById("sl_c4_r");
  if (!vEl || !rEl) return;

  const v = parseFloat(vEl.value);
  const r = parseFloat(rEl.value);
  document.getElementById("val_c4_v").textContent = v;
  document.getElementById("val_c4_r").textContent = r;

  const i = v / r;
  const p = v * i;
  const stage = document.getElementById("vis_c4_stage");
  if (stage) {
    stage.innerHTML = `
      <div class="flex flex-wrap items-center justify-center gap-6">
        <div class="text-center">
          <div class="text-xs text-slate-400">Intensidad (I = V / R)</div>
          <div class="text-xl font-bold text-amber-300 font-mono">${i.toFixed(2)} A (${(i*1000).toFixed(0)} mA)</div>
        </div>
        <div class="text-center">
          <div class="text-xs text-slate-400">Potencia en la Lámpara (P = V · I)</div>
          <div class="text-xl font-bold text-cyan-300 font-mono">${p.toFixed(1)} W</div>
        </div>
      </div>
    `;
  }
}

function updateTheorySim5() {
  const rEl = document.getElementById("sl_c5_r");
  const iEl = document.getElementById("sl_c5_i");
  const tEl = document.getElementById("sl_c5_t");
  if (!rEl || !iEl || !tEl) return;

  const r = parseFloat(rEl.value);
  const i = parseFloat(iEl.value);
  const t = parseFloat(tEl.value);
  document.getElementById("val_c5_r").textContent = r;
  document.getElementById("val_c5_i").textContent = i.toFixed(1);
  document.getElementById("val_c5_t").textContent = t;

  const eCal = r * i * i * t;
  const pot = r * i * i;
  const stage = document.getElementById("vis_c5_stage");
  if (stage) {
    stage.innerHTML = `
      <div class="text-base font-bold text-amber-300">
        🔥 Calor Disipado por Efecto Joule: E<sub>cal</sub> = ${r} Ω · (${i.toFixed(1)} A)<sup>2</sup> · ${t} s = <span class="text-white text-lg">${eCal.toFixed(1)} Joules</span>
      </div>
      <div class="text-xs text-cyan-200 font-mono">
        Potencia térmica instantánea: P = I² · R = ${pot.toFixed(1)} W &nbsp;(Nota cómo duplicar I multiplica el calor por 4)
      </div>
    `;
  }
}

function updateTheorySim6() {
  const modeEl = document.getElementById("sel_c6_mode");
  const rEl = document.getElementById("sl_c6_r");
  const unplugEl = document.getElementById("chk_c6_unplug");
  if (!modeEl || !rEl || !unplugEl) return;

  const mode = modeEl.value;
  const r = parseFloat(rEl.value);
  const unplugged = unplugEl.checked;
  document.getElementById("val_c6_r").textContent = r;

  const vTot = 220;
  const stage = document.getElementById("vis_c6_stage");
  if (!stage) return;

  if (mode === "serie") {
    if (unplugged) {
      stage.innerHTML = `
        <div class="text-rose-300 font-bold text-base">❌ Circuito en Serie Abierto: Al desconectar la Lámpara 1, se interrumpe el único camino y la Lámpara 2 SE APAGA (I = 0 A).</div>
      `;
    } else {
      const rEq = r + r;
      const iTot = vTot / rEq;
      stage.innerHTML = `
        <div class="text-amber-300 font-bold text-base">💡💡 Ambas lámparas en Serie encendidas a mitad de tensión (V₁ = V₂ = 110 V)</div>
        <div class="text-sm font-mono text-cyan-200">R_total = ${r} + ${r} = ${rEq} Ω &nbsp;|&nbsp; I_total = 220 V / ${rEq} Ω = ${iTot.toFixed(2)} A</div>
      `;
    }
  } else {
    if (unplugged) {
      const i2 = vTot / r;
      stage.innerHTML = `
        <div class="text-emerald-300 font-bold text-base">✅ Independencia en Paralelo: La Lámpara 1 está desconectada, pero la Lámpara 2 SIGUE FUNCIONANDO a 220 V (I₂ = ${i2.toFixed(2)} A).</div>
      `;
    } else {
      const rEq = r / 2;
      const iTot = vTot / rEq;
      stage.innerHTML = `
        <div class="text-cyan-300 font-bold text-base">💡💡 Ambas lámparas en Paralelo reciben 220 V completos y la corriente total se duplica</div>
        <div class="text-sm font-mono text-amber-200">R_total = ${r} / 2 = ${rEq.toFixed(1)} Ω &nbsp;|&nbsp; I_total = 220 V / ${rEq.toFixed(1)} Ω = ${iTot.toFixed(2)} A</div>
      `;
    }
  }
}

function updateTheorySim7() {
  const stimEl = document.getElementById("sl_c7_stim");
  const phaseEl = document.getElementById("sel_c7_phase");
  if (!stimEl || !phaseEl) return;

  const stim = parseFloat(stimEl.value);
  const phase = phaseEl.value;
  document.getElementById("val_c7_stim").textContent = "+" + stim;

  const stage = document.getElementById("vis_c7_stage");
  if (!stage) return;

  if (stim < 15) {
    stage.innerHTML = `
      <div class="text-rose-300 font-bold text-base">⚠️ Estímulo Subumbral (+${stim} mV &lt; +15 mV): Por la Ley de Todo o Nada, NO se abren los canales de Na⁺ y la membrana permanece en Reposo (-70 mV).</div>
    `;
    return;
  }

  const map = {
    reposo: "🔋 Estado Polarizado de Reposo (-70 mV): Exterior [+] rico en Na⁺ | Interior [-] mantenido por la bomba Na⁺/K⁺.",
    despol: "⚡ DESPOLARIZACIÓN (+30 mV): Se abren los canales de Sodio y ENTRA Na⁺ masivamente invirtiendo la polaridad interna a positiva.",
    repol: "🔄 REPOLARIZACIÓN (-70 mV): Se cierran los canales de Na⁺, se abren los de Potasio y SALE K⁺ recuperando el potencial negativo interno."
  };
  stage.innerHTML = `<div class="text-emerald-300 font-bold text-base">${map[phase]}</div>`;
}

function updateTheorySim8() {
  const dEl = document.getElementById("sl_c8_diam");
  const bpmEl = document.getElementById("sl_c8_bpm");
  if (!dEl || !bpmEl) return;

  const diam = parseFloat(dEl.value);
  const bpm = parseFloat(bpmEl.value);
  document.getElementById("val_c8_diam").textContent = diam;
  document.getElementById("val_c8_bpm").textContent = bpm;

  const vAmiel = (diam * 0.5).toFixed(1);
  const vMiel = (diam * 5.0).toFixed(0);
  const rrSec = (60 / bpm).toFixed(2);

  const stage = document.getElementById("vis_c8_stage");
  if (stage) {
    stage.innerHTML = `
      <div class="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm">
        <div class="p-2.5 rounded-xl bg-slate-900/90">
          <div class="text-amber-300 font-bold">Velocidad Neuronal (Diámetro ${diam} μm)</div>
          <div class="text-slate-200">• Fibra Amielínica (continua): <strong>${vAmiel} m/s</strong></div>
          <div class="text-cyan-300">• Fibra Mielínica (saltatoria en Nódulos de Ranvier): <strong>${vMiel} m/s</strong></div>
        </div>
        <div class="p-2.5 rounded-xl bg-slate-900/90">
          <div class="text-emerald-300 font-bold">Monitor ECG — Nódulo Sinusal (${bpm} lat/min)</div>
          <div class="text-slate-200">• Intervalo entre latidos: <strong>${rrSec} s</strong> (${bpm > 100 ? 'Taquicardia sinusal' : bpm < 60 ? 'Bradicardia sinusal' : 'Ritmo sinusal normal'})</div>
        </div>
      </div>
    `;
  }
}

function initActiveTheorySimulators() {
  updateTheorySim1();
  updateTheorySim2();
  updateTheorySim3();
  updateTheorySim4();
  updateTheorySim5();
  updateTheorySim6();
  updateTheorySim7();
  updateTheorySim8();
}

