function updateExSim1() {
  const sel = document.getElementById("exSim1_state");
  const out = document.getElementById("exSim1_out");
  if (!sel || !out) return;
  if (sel.value === "sana") {
    out.textContent = "Piel sana (R ≈ 40.000 Ω) a 220 V ⟶ I = 0,0055 A (5,5 mA). Alta oposición al paso de corriente.";
  } else {
    out.textContent = "Herida con sangre (R ≈ 800 Ω por electrolitos del plasma) a 220 V ⟶ I = 0,275 A (275 mA). ¡La resistencia es mucho MENOR!";
  }
}

function updateExSim2() {
  const sl = document.getElementById("exSim2_r");
  const val = document.getElementById("exSim2_rVal");
  const out = document.getElementById("exSim2_out");
  if (!sl || !val || !out) return;
  const mOhm = parseFloat(sl.value);
  val.textContent = mOhm.toLocaleString("es-AR");
  const ohm = mOhm / 1000;
  const amp = 220 / ohm;
  out.textContent = `R = ${ohm} Ω  ⟶  I = 220 V / ${ohm} Ω = ${amp.toFixed(3)} A (${(amp*1000).toFixed(1)} mA)`;
}

function updateExSim3() {
  const sl = document.getElementById("exSim3_e");
  const val = document.getElementById("exSim3_eVal");
  const out = document.getElementById("exSim3_out");
  if (!sl || !val || !out) return;
  const eJ = parseFloat(sl.value);
  val.textContent = eJ;
  const tSec = eJ / (1200 * 19 * 19);
  out.textContent = `t = ${eJ} J / (1200 Ω · 19² A²) = ${tSec.toExponential(3)} s (${(tSec*1000).toFixed(3)} ms)`;
}

function updateExSim4() {
  const sl = document.getElementById("exSim4_p");
  const val = document.getElementById("exSim4_pVal");
  const out = document.getElementById("exSim4_out");
  if (!sl || !val || !out) return;
  const pW = parseFloat(sl.value);
  val.textContent = pW;
  const iA = pW / 230;
  out.textContent = `I = ${pW} W / 230 V = ${iA.toFixed(2)} A  (4 cifras significativas)`;
}

function updateExSim5() {
  const sl = document.getElementById("exSim5_r");
  const val = document.getElementById("exSim5_rVal");
  const out = document.getElementById("exSim5_out");
  if (!sl || !val || !out) return;
  const r = parseFloat(sl.value);
  val.textContent = r;
  const iMa = (220 / r) * 1000;
  out.textContent = `I_fuga = 220 V / ${r} Ω = ${iMa.toFixed(1)} mA ⟶ ${iMa > 40 ? '¡Supera 40 mA! El disyuntor ABRE el circuito y protege a la persona' : 'Menor a 40 mA'}`;
}

function updateExSim6() {
  const sl = document.getElementById("exSim6_r");
  const val = document.getElementById("exSim6_rVal");
  const out = document.getElementById("exSim6_out");
  if (!sl || !val || !out) return;
  const r = parseFloat(sl.value);
  val.textContent = r;
  const iS = 220 / (2 * r);
  const iP = 220 / (r / 2);
  out.textContent = `En Serie: R_eq = ${2*r} Ω, I = ${iS.toFixed(2)} A  |  En Paralelo: R_eq = ${(r/2).toFixed(1)} Ω, I = ${iP.toFixed(2)} A`;
}

function initActiveExerciseSimulators() {
  updateExSim1();
  updateExSim2();
  updateExSim3();
  updateExSim4();
  updateExSim5();
  updateExSim6();
}

