function getCurrentUnitConcepts() {
  if (currentUnit === "u6") return UNIDAD_6_CONCEPTS;
  return OTHER_UNITS_CONCEPTS[currentUnit] || UNIDAD_6_CONCEPTS;
}

function selectConceptPill(conceptId) {
  currentConceptId = conceptId;
  renderConceptPillsAndDevelopment();
}

function renderConceptPillsAndDevelopment() {
  const pillsBar = document.getElementById("dynamicConceptPillsBar");
  const devContainer = document.getElementById("unitDevelopmentContainer");
  if (!pillsBar || !devContainer) return;

  const concepts = getCurrentUnitConcepts();
  if (!concepts.some(c => c.id === currentConceptId)) {
    currentConceptId = concepts[0].id;
  }

  // Solo botones de cada concepto individual (sin botón 'Todos los conceptos')
  pillsBar.innerHTML = concepts.map(c => `
    <button type="button" onclick="selectConceptPill('${c.id}')" class="concept-btn ${currentConceptId === c.id ? 'active' : ''}">
      ${c.shortBtn}
    </button>
  `).join("");

  const activeConcept = concepts.find(c => c.id === currentConceptId) || concepts[0];

  devContainer.innerHTML = `
    <article class="p-4 md:p-7 rounded-3xl bg-slate-950/30 space-y-6">
      <div class="flex flex-col md:flex-row items-center justify-center gap-5 pb-2">
        <img src="${activeConcept.capyImg}" alt="Capibara" class="w-20 h-20 object-contain sprite-no-bg anim-capy">
        <div class="max-w-2xl text-center">
          <h3 class="text-2xl md:text-3xl font-bold text-amber-300 font-tier-2">${activeConcept.title}</h3>
        </div>
        <img src="${activeConcept.sciIcon}" alt="Ícono Ciencia" class="w-16 h-16 object-contain sprite-no-bg anim-sci-icon">
      </div>

      <div class="space-y-5">
        ${activeConcept.theoryHtml}
      </div>

      <div class="pt-4 text-center">
        <div class="pdf-ref-footer">
          <img src="assets/lab_circle.webp" alt="Laboratorio" class="w-8 h-8 object-contain sprite-no-bg">
          <span class="text-sm text-cyan-200">
            📚 <strong>Para profundizar en el PDF:</strong> Este tema se encuentra en <strong>${activeConcept.pdfPages}</strong>
          </span>
          <button type="button" onclick="openOriginalFileViewer('${currentUnit}', ${activeConcept.pdfPageNum})" class="px-4 py-1.5 text-xs font-bold rounded-full bg-amber-400 hover:bg-amber-300 text-slate-950 transition">
            📄 Abrir PDF Original en Página ${activeConcept.pdfPageNum}
          </button>
          <button type="button" onclick="jumpToVideoConcept('${activeConcept.videoRefId}', ${activeConcept.videoRefSec})" class="px-4 py-1.5 text-xs font-bold rounded-full bg-cyan-400/25 hover:bg-cyan-400/40 text-cyan-100 transition">
            🎥 Ver en Video
          </button>
        </div>
      </div>
    </article>
  `;

  initActiveTheorySimulators();
}

// ============================================================================
// 11. CAJAS INFERIORES: EJERCICIOS Y SIMULACRO DE PARCIAL (ETIQUETAS LIMPIAS)
// ============================================================================
function setBottomMode(mode) {
  currentBottomMode = mode;
  renderBottomBoxes();
}

function selectGuidedExercise(exId) {
  currentExerciseId = exId;
  renderBottomBoxes();
}

function selectSimProblem(simId) {
  currentSimId = simId;
  renderBottomBoxes();
}

function confirmGuidedAttempt(exId) {
  const inputEl = document.getElementById("attemptInput_" + exId);
  const userText = inputEl ? inputEl.value.trim() : "";
  unlockedResolutions[exId] = {
    unlocked: true,
    userAttempt: userText || "Planteo verificado paso a paso."
  };
  renderBottomBoxes();
}

function evaluateSimulacro(simId) {
  const sim = EXAM_SIM_PROBLEMS.find(s => s.id === simId);
  if (!sim) return;

  const procEl = document.getElementById("simProc_" + simId);
  const procText = procEl ? procEl.value.trim() : "";

  let feedbackTitle = "";
  let feedbackBody = "";
  let isCorrect = false;

  if (sim.options) {
    const sel = document.querySelector(`input[name="simOpt_${simId}"]:checked`);
    const chosen = sel ? sel.value : "";
    if (!chosen) {
      feedbackTitle = "⚠️ Selecciona primero una de las opciones (A, B o C)";
      feedbackBody = "Elige una opción y escribe tu justificación física para evaluar tanto el procedimiento como el resultado.";
      unlockedResolutions[simId] = { unlocked: false, feedbackTitle, feedbackBody, isCorrect: false };
      renderBottomBoxes();
      return;
    }
    isCorrect = (chosen === sim.correctOption);
    feedbackTitle = isCorrect
      ? "✅ ¡Respuesta y razonamiento biofísico correctos! (Opción " + chosen + ")"
      : "❌ Elegiste la opción " + chosen + ", pero la correcta es la " + sim.correctOption;
    feedbackBody = procText
      ? `Tu justificación registrada: «${procText}». Revisa debajo la resolución completa.`
      : "Recuerda en el examen redactar siempre la justificación completa.";
  } else {
    const numEl = document.getElementById("simNum_" + simId);
    const rawVal = numEl ? numEl.value.trim().replace(",", ".") : "";
    const parsed = parseFloat(rawVal);
    if (isNaN(parsed)) {
      feedbackTitle = "⚠️ Ingresa un valor numérico en la casilla de respuesta";
      feedbackBody = "Escribe tu resultado numérico y las ecuaciones que planteaste para evaluar tu resolución.";
      unlockedResolutions[simId] = { unlocked: false, feedbackTitle, feedbackBody, isCorrect: false };
      renderBottomBoxes();
      return;
    }
    const relErr = Math.abs(parsed - sim.numericTarget) / sim.numericTarget;
    isCorrect = relErr <= sim.toleranceRel;
    if (isCorrect) {
      feedbackTitle = `✅ ¡Cálculo Exacto! Tu valor (${parsed} ${sim.unitTarget}) es correcto`;
      feedbackBody = "Revisa a la derecha el desarrollo completo con despeje algebraico y análisis dimensional.";
    } else {
      feedbackTitle = `🔍 Ingresaste ${parsed}, y el valor esperado es ${sim.numericTarget} ${sim.unitTarget}`;
      feedbackBody = "Revisa en la caja derecha la conversión de unidades al Sistema Internacional y el despeje paso a paso.";
    }
  }

  unlockedResolutions[simId] = {
    unlocked: true,
    feedbackTitle,
    feedbackBody,
    isCorrect
  };
  renderBottomBoxes();
}

function renderBottomBoxes() {
  const leftBox = document.getElementById("bottomLeftExercisesBox");
  const rightBox = document.getElementById("bottomRightResolutionsBox");
  if (!leftBox || !rightBox) return;

  if (currentBottomMode === "guided") {
    const ex = GUIDED_EXERCISES.find(e => e.id === currentExerciseId) || GUIDED_EXERCISES[0];
    const state = unlockedResolutions[ex.id] || { unlocked: false, userAttempt: "" };

    leftBox.innerHTML = `
      <div class="space-y-5">
        <div class="flex flex-wrap items-center justify-center gap-3">
          <button type="button" onclick="setBottomMode('guided')" class="concept-btn active">
            Ejercicios
          </button>
          <button type="button" onclick="setBottomMode('simulacro')" class="concept-btn">
            Simulacro de Parcial
          </button>
        </div>

        <h3 class="text-xl md:text-2xl font-bold text-amber-300 font-tier-2 text-center">
          Ejercicios
        </h3>

        <div class="flex flex-wrap items-center justify-center gap-2">
          ${GUIDED_EXERCISES.map((item, idx) => `
            <button type="button" onclick="selectGuidedExercise('${item.id}')" class="px-3.5 py-1.5 text-xs rounded-full font-tier-3 transition ${item.id === ex.id ? 'bg-amber-400 text-slate-950 font-bold shadow-md' : 'bg-slate-900/75 text-slate-200 hover:bg-slate-800'}">
              Ejercicio ${idx + 1} ${unlockedResolutions[item.id]?.unlocked ? '✓' : ''}
            </button>
          `).join("")}
        </div>

        <div class="p-4 md:p-5 rounded-3xl bg-slate-950/45 space-y-3">
          <div class="flex items-center justify-center gap-3">
            <img src="assets/capy_labcoat.webp" alt="Capibara" class="w-14 h-14 object-contain sprite-no-bg anim-capy">
            <h4 class="text-lg md:text-xl font-bold text-white font-tier-2 text-center">${ex.title}</h4>
          </div>
          <p class="prose-justify-sm whitespace-pre-line !mb-2">${ex.statement}</p>
          ${ex.simHtml || ""}
        </div>

        <div class="p-4 md:p-5 rounded-3xl bg-slate-950/45 space-y-3">
          <div class="text-cyan-300 font-bold text-base font-tier-2 text-center">1- Datos, Incógnitas y Unidades en el Sistema Internacional</div>
          <div class="space-y-2 prose-justify-sm">
            ${ex.step1_data.map(d => `<div>• ${d}</div>`).join("")}
          </div>

          <div class="text-cyan-300 font-bold text-base pt-2 font-tier-2 text-center">2- Esquema Mental y Diagrama del Sistema</div>
          <p class="prose-justify-sm">${ex.step2_diagram}</p>

          <div class="text-cyan-300 font-bold text-base pt-2 font-tier-2 text-center">3- Principios y Leyes Físicas a Aplicar</div>
          <div class="space-y-2 prose-justify-sm !mb-0">
            ${ex.step3_laws.map(l => `<div>• ${l}</div>`).join("")}
          </div>
        </div>

        <div class="trap-nebula-card space-y-3 text-center">
          <div class="font-bold text-amber-200 text-base font-tier-2">🤔 Confirmación de tu Planteo</div>
          <p class="prose-justify-sm !text-center !mb-2 text-amber-100">${ex.hintQuestion}</p>
          <input
            id="attemptInput_${ex.id}"
            type="text"
            value="${state.userAttempt || ''}"
            placeholder="Escribe tu planteo o resultado estimado aquí..."
            class="w-full max-w-md mx-auto block px-4 py-2 rounded-xl bg-slate-950/80 text-white text-center text-sm focus:outline-none focus:ring-2 focus:ring-amber-400">
          <div class="pt-1">
            <button type="button" onclick="confirmGuidedAttempt('${ex.id}')" class="px-5 py-2.5 rounded-full font-bold text-sm bg-gradient-to-r from-amber-400 via-amber-500 to-cyan-400 text-slate-950 hover:opacity-95 transition shadow-lg font-tier-3">
              ✅ Confirmar Planteo y Ver Resolución a la Derecha →
            </button>
          </div>
        </div>
      </div>
    `;

    if (!state.unlocked) {
      rightBox.innerHTML = `
        <div class="h-full flex flex-col items-center justify-center p-6 space-y-5 text-center">
          <img src="assets/capy_idea.webp" alt="Capibara pensando" class="w-24 h-24 object-contain sprite-no-bg anim-capy">
          <h3 class="text-xl md:text-2xl font-bold text-amber-300 font-tier-2">
            Resoluciones de Ejercicios
          </h3>
          <p class="prose-justify-sm max-w-md">
            Revisa primero en la caja izquierda los datos, unidades, esquema mental y leyes a aplicar para <strong>${ex.title}</strong>. Cuando confirmes tu intento se desplegará aquí el desarrollo paso a paso con análisis dimensional y resultado recuadrado.
          </p>
          <button type="button" onclick="confirmGuidedAttempt('${ex.id}')" class="px-5 py-2 rounded-full font-bold text-sm bg-amber-400 hover:bg-amber-300 text-slate-950 transition shadow-md font-tier-3">
            🔓 Mostrar Resolución Completa
          </button>
        </div>
      `;
    } else {
      rightBox.innerHTML = `
        <div class="space-y-5">
          <div class="flex items-center justify-center gap-3 text-center">
            <img src="assets/capy_doctor.webp" alt="Capibara" class="w-16 h-16 object-contain sprite-no-bg anim-capy">
            <div>
              <h3 class="text-xl md:text-2xl font-bold text-white font-tier-2">${ex.title}</h3>
            </div>
            <img src="assets/icon_lightbulb.webp" alt="Idea" class="w-12 h-12 object-contain sprite-no-bg anim-sci-icon">
          </div>

          <div class="p-4 md:p-5 rounded-3xl bg-slate-950/45">
            ${ex.directResolutionHtml}
          </div>
        </div>
      `;
    }
  } else {
    const sim = EXAM_SIM_PROBLEMS.find(s => s.id === currentSimId) || EXAM_SIM_PROBLEMS[0];
    const state = unlockedResolutions[sim.id] || { unlocked: false };

    leftBox.innerHTML = `
      <div class="space-y-5">
        <div class="flex flex-wrap items-center justify-center gap-3">
          <button type="button" onclick="setBottomMode('guided')" class="concept-btn">
            Ejercicios
          </button>
          <button type="button" onclick="setBottomMode('simulacro')" class="concept-btn active">
            Simulacro de Parcial
          </button>
        </div>

        <h3 class="text-xl md:text-2xl font-bold text-amber-300 font-tier-2 text-center">
          Simulacro de Parcial
        </h3>

        <div class="flex flex-wrap items-center justify-center gap-2">
          ${EXAM_SIM_PROBLEMS.map((s, idx) => `
            <button type="button" onclick="selectSimProblem('${s.id}')" class="px-3.5 py-1.5 text-xs rounded-full font-tier-3 transition ${s.id === sim.id ? 'bg-amber-400 text-slate-950 font-bold shadow-md' : 'bg-slate-900/75 text-slate-200 hover:bg-slate-800'}">
              Problema ${idx + 1} ${unlockedResolutions[s.id]?.unlocked ? (unlockedResolutions[s.id]?.isCorrect ? '✅' : '🔍') : ''}
            </button>
          `).join("")}
        </div>

        <div class="p-4 md:p-5 rounded-3xl bg-slate-950/45 space-y-3.5">
          <div class="flex items-center justify-center gap-3">
            <img src="assets/capy_stars_jump.webp" alt="Capibara" class="w-14 h-14 object-contain sprite-no-bg anim-capy">
            <span class="px-3 py-0.5 rounded-full text-xs bg-purple-500/30 text-purple-200 font-tier-3">${sim.level}</span>
          </div>
          <h4 class="text-lg md:text-xl font-bold text-white font-tier-2 text-center">${sim.title}</h4>
          <p class="prose-justify-sm whitespace-pre-line">${sim.statement}</p>

          ${sim.options ? `
            <div class="space-y-2.5 pt-1 text-sm">
              ${sim.options.map(opt => `
                <label class="block p-3 rounded-2xl bg-slate-950/70 hover:bg-slate-900/95 cursor-pointer transition text-slate-100 text-left">
                  <input type="radio" name="simOpt_${sim.id}" value="${opt.val}" class="mr-2 accent-amber-400">
                  <span>${opt.text}</span>
                </label>
              `).join("")}
            </div>
          ` : `
            <div class="pt-1 text-center">
              <label class="block text-xs text-cyan-300 mb-1.5 font-tier-3">Resultado numérico final (${sim.unitTarget}):</label>
              <input id="simNum_${sim.id}" type="text" placeholder="${sim.inputPlaceholder}" class="w-full max-w-md mx-auto block px-4 py-2 rounded-xl bg-slate-950/85 text-white text-center text-sm focus:outline-none focus:ring-2 focus:ring-amber-400">
            </div>
          `}

          <div class="pt-2 text-center">
            <label class="block text-xs text-amber-200 mb-1.5 font-tier-3">Procedimiento (ecuación despejada y pasaje de unidades):</label>
            <textarea id="simProc_${sim.id}" rows="2" placeholder="Escribe cómo despejaste y qué unidades convertiste..." class="w-full max-w-md mx-auto block p-3 rounded-xl bg-slate-950/85 text-white text-center text-xs md:text-sm focus:outline-none focus:ring-2 focus:ring-cyan-400"></textarea>
          </div>

          <div class="pt-2 text-center">
            <button type="button" onclick="evaluateSimulacro('${sim.id}')" class="px-5 py-2.5 rounded-full font-bold text-sm bg-gradient-to-r from-amber-400 via-amber-500 to-cyan-400 text-slate-950 hover:opacity-95 transition shadow-lg font-tier-3">
              📝 Evaluar Respuesta y Procedimiento →
            </button>
          </div>
        </div>
      </div>
    `;

    if (!state.unlocked && !state.feedbackTitle) {
      rightBox.innerHTML = `
        <div class="h-full flex flex-col items-center justify-center p-6 space-y-4 text-center">
          <img src="assets/capy_balloons.webp" alt="Capibara" class="w-24 h-24 object-contain sprite-no-bg anim-capy">
          <h3 class="text-xl md:text-2xl font-bold text-amber-300 font-tier-2">
            Corrección de Simulacro de Parcial
          </h3>
          <p class="prose-justify-sm max-w-md">
            Completa tu planteo y tu respuesta para <strong>${sim.title}</strong> en la columna izquierda y presiona Evaluar para ver la corrección detallada paso a paso.
          </p>
        </div>
      `;
    } else {
      rightBox.innerHTML = `
        <div class="space-y-4">
          <div class="trap-nebula-card text-center">
            <div class="font-bold text-base md:text-lg font-tier-2">${state.feedbackTitle}</div>
            <p class="prose-justify-sm !text-center mt-2 !mb-0">${state.feedbackBody}</p>
          </div>
          ${state.unlocked ? `
            <div class="p-4 md:p-5 rounded-3xl bg-slate-950/45">
              ${sim.resolutionHtml}
            </div>
          ` : ""}
        </div>
      `;
    }
  }

  initActiveExerciseSimulators();
}

// ============================================================================
// 12. NAVEGACIÓN DE LA BARRA STICKY
// ============================================================================
function switchTopNav(target) {
  closeOriginalFileViewer();
  const menu = document.getElementById("archivosDropdownMenu");
  if (menu) menu.classList.add("hidden");

  const btns = ["navBtnU6", "navBtnU7", "navBtnU8", "navBtnEj", "navBtnParcial"];
  btns.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.classList.remove("active");
  });

  if (target === "u6" || target === "u7" || target === "u8") {
    currentUnit = target;
    const allVids = getAllVideosForUnit(currentUnit);
    activeVideoObj = allVids[0];
    const concepts = getCurrentUnitConcepts();
    currentConceptId = concepts[0].id;

    const activeBtn = document.getElementById("navBtn" + target.toUpperCase());
    if (activeBtn) activeBtn.classList.add("active");

    renderVideoBars();
    renderVideoConceptsBox();
    initOrUpdateYouTubeEmbed(null);
    renderConceptPillsAndDevelopment();
    renderFormulaSheet(currentUnit);
    window.scrollTo({ top: 0, behavior: "smooth" });
  } else if (target === "ejercicios") {
    const activeBtn = document.getElementById("navBtnEj");
    if (activeBtn) activeBtn.classList.add("active");
    setBottomMode("guided");
    const sec = document.getElementById("bottomExercisesSection");
    if (sec) sec.scrollIntoView({ behavior: "smooth", block: "start" });
  } else if (target === "parcial") {
    const activeBtn = document.getElementById("navBtnParcial");
    if (activeBtn) activeBtn.classList.add("active");
    setBottomMode("simulacro");
    const sec = document.getElementById("bottomExercisesSection");
    if (sec) sec.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

window.addEventListener("DOMContentLoaded", () => {
  initStarfieldAnimation();
  loadSavedTimes();
  activeVideoObj = getAllVideosForUnit("u6")[0];
  renderFormulaSheet("u6");
  renderVideoBars();
  renderVideoConceptsBox();
  initOrUpdateYouTubeEmbed(null);
  startFallbackProgressTimer();
  renderConceptPillsAndDevelopment();
  renderBottomBoxes();
});
